(()=>{const checkout='https://pay.cakto.com.br/qc254wc_536920';const incoming=new URLSearchParams(location.search);document.querySelectorAll('a.cta').forEach(a=>{const target=new URL(checkout);incoming.forEach((value,key)=>{if(/^utm_/i.test(key)||['fbclid','gclid','xcod','src','sck'].includes(key))target.searchParams.set(key,value)});a.href=target.href;});})();
// Configure um prazo real, com fuso horário, para ativar o cronômetro.
// Exemplo de formato: AAAA-MM-DDTHH:mm:ss-03:00. Não reinicia por visitante.
const OFFER_DEADLINE = null;
(()=>{const section=document.getElementById('prazo-oferta');if(!OFFER_DEADLINE||!section)return;const deadline=new Date(OFFER_DEADLINE);if(!Number.isFinite(deadline.getTime()))return;let interval;const tick=()=>{const remaining=deadline.getTime()-Date.now();if(remaining<=0){section.hidden=true;if(interval)clearInterval(interval);return;}section.hidden=false;const seconds=Math.floor(remaining/1000);const units={days:Math.floor(seconds/86400),hours:Math.floor(seconds/3600)%24,minutes:Math.floor(seconds/60)%60,seconds:seconds%60};Object.entries(units).forEach(([key,value])=>{section.querySelector('[data-unit="'+key+'"]').textContent=String(value).padStart(2,'0')});};section.querySelector('.deadline-label').textContent='Condição válida até '+deadline.toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'})+' (horário de Brasília).';tick();interval=setInterval(tick,1000);})();
